#!/usr/bin/env node
/**
 * PUVIMA Consultancy — Database Restoration Utility
 * Restores SQL backup file generated by backup_db.js with checksum verification.
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
require('dotenv').config({ path: path.resolve(__dirname, '../backend/.env') });

const db = require('../backend/src/config/database');

async function runRestore() {
  const args = process.argv.slice(2);
  const isDryRun = args.includes('--dry-run');
  const fileArg = args.find(a => !a.startsWith('--'));

  console.log('====================================================');
  console.log(' PUVIMA Consultancy — Database Restore Utility');
  console.log('====================================================');

  if (!fileArg) {
    console.error('Usage: node scripts/restore_db.js <path-to-sql-backup> [--dry-run]');
    process.exit(1);
  }

  const backupFilePath = path.resolve(process.cwd(), fileArg);
  if (!fs.existsSync(backupFilePath)) {
    console.error(`[RESTORE FAILED] Backup file not found: ${backupFilePath}`);
    process.exit(1);
  }

  const sqlContent = fs.readFileSync(backupFilePath, 'utf8');
  console.log(`[FILE LOADED] ${backupFilePath} (${Math.round(sqlContent.length / 1024)} KB)`);

  // Optional Checksum verification if meta file exists
  const metaFilePath = backupFilePath.replace(/\.sql$/, '.meta.json');
  if (fs.existsSync(metaFilePath)) {
    try {
      const meta = JSON.parse(fs.readFileSync(metaFilePath, 'utf8'));
      const computedHash = crypto.createHash('sha256').update(sqlContent).digest('hex');
      if (meta.sha256Checksum && meta.sha256Checksum !== computedHash) {
        console.error('[INTEGRITY CHECK FAILED] Backup file checksum does not match metadata file!');
        process.exit(1);
      }
      console.log(' ✔ Checksum verified against metadata (SHA256 Match)');
    } catch (e) {
      console.warn(' ⚠ Warning: Could not parse metadata file for checksum verification.');
    }
  }

  // Parse SQL statements
  const statements = sqlContent
    .split(/;\s*[\r\n]+/)
    .map(s => s.trim())
    .filter(s => s.length > 0 && !s.startsWith('--'));

  console.log(`[PARSED] ${statements.length} executable SQL statements found.`);

  if (isDryRun) {
    console.log('[DRY RUN MODE] Statements verified. No database changes were applied.');
    process.exit(0);
  }

  const connectionStatus = await db.testConnection();
  if (!connectionStatus.isConnected) {
    console.error('[RESTORE FAILED] Database is not accessible:', connectionStatus.message);
    process.exit(1);
  }

  console.log('[EXECUTING RESTORE] Applying backup statements to database...');

  let successCount = 0;
  for (const stmt of statements) {
    try {
      await db.query(stmt);
      successCount++;
    } catch (err) {
      console.warn(` ⚠ Statement warning: ${err.message}`);
    }
  }

  console.log('----------------------------------------------------');
  console.log(`[RESTORE COMPLETED] ${successCount}/${statements.length} statements successfully executed.`);
  console.log('====================================================');
  process.exit(0);
}

runRestore().catch(err => {
  console.error('[FATAL RESTORE ERROR]:', err);
  process.exit(1);
});

